extern alias apiv6;
using System.Net;using System.Net.Http.Json;using System.Text.Json;using Microsoft.AspNetCore.Hosting;using Microsoft.AspNetCore.Mvc.Testing;using Microsoft.Extensions.DependencyInjection;using Npgsql;using SanSo.Api.Modules;using Xunit;using V6Program=apiv6::Program;
namespace SanSo.Api.V6.Tests;
public sealed class PostgresInventoryLifecycleHttpV6Tests
{
 [Fact]public async Task AuthenticatedGetReserveReleaseIsDurableGuardedAndIdempotent(){var cs=Environment.GetEnvironmentVariable("SANSO_RUNTIME_POSTGRES");if(string.IsNullOrWhiteSpace(cs))return;var tenant=Guid.NewGuid();var product=Guid.NewGuid();var location=Guid.NewGuid();var sku=$"LIFE-{Guid.NewGuid():N}";await Seed(cs,tenant,product,location,sku);await using var factory=new WebApplicationFactory<V6Program>().WithWebHostBuilder(x=>{x.UseEnvironment("Development");x.UseSetting("ConnectionStrings:Postgres",cs);});using var client=factory.CreateClient();var identity=factory.Services.GetRequiredService<IdentityService>();var secret=IdentityService.GenerateTotpSecret();var email=$"life-{Guid.NewGuid():N}@example.invalid";var user=identity.Register(email,"Inventory lifecycle owner","Long-Safe-Lifecycle-Password-2026!",secret);identity.AddMembership(tenant.ToString(),user.Id,OrgRole.Owner);var login=await client.PostAsJsonAsync("/api/auth/login",new{email,password="Long-Safe-Lifecycle-Password-2026!",tenantId=tenant.ToString(),totpCode=IdentityService.CurrentTotp(secret)});var token=(await login.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("token").GetString()!;Assert.Equal(HttpStatusCode.Unauthorized,(await client.GetAsync($"/api/inventory/{sku}")).StatusCode);Assert.Equal(2,(await Get(client,sku,token,tenant)).GetProperty("available").GetInt32());var reserve=await Post(client,$"/api/inventory/{sku}/reserve",new{quantity=2,sourceKey="reserve-life"},token,tenant);Assert.Equal(HttpStatusCode.OK,reserve.StatusCode);Assert.Equal(0,(await reserve.Content.ReadFromJsonAsync<JsonElement>()).GetProperty("available").GetInt32());var over=await Post(client,$"/api/inventory/{sku}/release",new{quantity=3,sourceKey="release-over"},token,tenant);Assert.Equal(HttpStatusCode.BadRequest,over.StatusCode);var release=await Post(client,$"/api/inventory/{sku}/release",new{quantity=1,sourceKey="release-life"},token,tenant);Assert.Equal(HttpStatusCode.OK,release.StatusCode);var retry=await Post(client,$"/api/inventory/{sku}/release",new{quantity=1,sourceKey="release-life"},token,tenant);Assert.Equal(HttpStatusCode.OK,retry.StatusCode);var final=await Get(client,sku,token,tenant);Assert.Equal(1,final.GetProperty("reserved").GetInt32());Assert.Equal(2,final.GetProperty("version").GetInt64());}
 static async Task<JsonElement> Get(HttpClient c,string sku,string token,Guid tenant){using var r=new HttpRequestMessage(HttpMethod.Get,$"/api/inventory/{sku}");Auth(r,token,tenant);var response=await c.SendAsync(r);if(response.StatusCode!=HttpStatusCode.OK)throw new Xunit.Sdk.XunitException($"GET {(int)response.StatusCode}: {await response.Content.ReadAsStringAsync()}");return await response.Content.ReadFromJsonAsync<JsonElement>();}static async Task<HttpResponseMessage> Post(HttpClient c,string path,object body,string token,Guid tenant){using var r=new HttpRequestMessage(HttpMethod.Post,path){Content=JsonContent.Create(body)};Auth(r,token,tenant);return await c.SendAsync(r);}static void Auth(HttpRequestMessage r,string token,Guid tenant){r.Headers.Authorization=new("Bearer",token);r.Headers.Add("X-Tenant-Id",tenant.ToString());}static async Task Seed(string cs,Guid tenant,Guid product,Guid location,string sku){await using var c=new NpgsqlConnection(cs);await c.OpenAsync();await using var tx=await c.BeginTransactionAsync();foreach(var item in new[]{(Sql:"INSERT INTO organizations(id,slug,name) VALUES($1,$2,'Lifecycle test')",Args:new object[]{tenant,$"lifecycle-{tenant:N}"}),(Sql:"INSERT INTO products(id,organization_id,name,canonical_sku) VALUES($1,$2,'Lifecycle SKU',$3)",Args:new object[]{product,tenant,sku}),(Sql:"INSERT INTO inventory_locations(id,organization_id,code,name) VALUES($1,$2,'MAIN','Main')",Args:new object[]{location,tenant}),(Sql:"INSERT INTO inventory_balances(organization_id,product_id,location_id,on_hand,reserved,quarantine) VALUES($1,$2,$3,2,0,0)",Args:new object[]{tenant,product,location})}){await using var q=c.CreateCommand();q.Transaction=tx;q.CommandText=item.Sql;foreach(var value in item.Args)q.Parameters.AddWithValue(value);await q.ExecuteNonQueryAsync();}await tx.CommitAsync();}
}
